  "help.articles.whatAreStudioCredits.title": "Wat zijn Studio Credits?",
  "help.articles.whatAreStudioCredits.description": "Credits zijn de prepaid valuta voor factureerbare Studio-acties.",
  "help.articles.whatAreStudioCredits.body1": "Je besteedt credits bij provider-acties zoals Motion-renders, stemgeneratie, beeldgeneratie of exports.",
  "help.articles.whatAreStudioCredits.body2": "Koop credit packs wanneer je wilt of upgrade je plan voor korting. Je saldo staat in de header en op het billing-dashboard.",
  "help.articles.howSubscriptionsWork.title": "Hoe werken abonnementen?",
  "help.articles.howSubscriptionsWork.description": "Plannen geven kortingen en voordelen — niet op elk niveau automatisch maandelijkse credits.",
  "help.articles.howSubscriptionsWork.body1": "Creator-, Pro- en Studio-plannen verlagen creditprijzen en ontgrendelen workflow-voordelen.",
  "help.articles.howSubscriptionsWork.body2": "Abonnementen worden via Stripe beheerd. Upgrade, downgrade of annuleer via Account → Billing.",
  "help.articles.doCreditsExpire.title": "Verlopen credits?",
  "help.articles.doCreditsExpire.description": "Gekochte credits volgen het billingbeleid van je account.",
  "help.articles.doCreditsExpire.body1": "Onder het huidige beleid blijven gekochte credits op je wallet na opzegging, tenzij een adminbeleid anders bepaalt. Promotionele credits kunnen aparte regels hebben.",
  "help.articles.whatHappensWhenICancel.title": "Wat gebeurt er bij opzeggen?",
  "help.articles.whatHappensWhenICancel.description": "Je abonnement eindigt aan het einde van de periode; credits blijven meestal staan.",
  "help.articles.whatHappensWhenICancel.body1": "Bij opzeggen stoppen plankortingen aan het einde van de facturatieperiode. Ongebruikte gekochte credits blijven beschikbaar.",
  "help.articles.howMuchDoActionsCost.title": "Wat kosten Studio-acties?",
  "help.articles.howMuchDoActionsCost.description": "Live creditprijzen uit de openbare prijscatalogus.",
  "help.articles.howMuchDoActionsCost.body1": "Prijzen hieronder komen uit dezelfde catalogus als billing en de assistant — niet hardcoded in dit artikel.",
  "help.articles.howMotionPricingWorks.title": "Hoe werkt Motion-prijzen?",
  "help.articles.howMotionPricingWorks.description": "Motion-renders gebruiken Vidu provider credits weerspiegeld in Studio-prijzen.",
  "help.articles.howMotionPricingWorks.body1": "Elke transition of story-render reserveert credits vooraf. Werkelijk providerverbruik wordt gemeten voor economie.",
  "help.articles.howMotionPricingWorks.body2": "Hergebruik bestaande personages en achtergronden om dubbele generatiekosten te vermijden.",
  "help.articles.howCampaignCodesWork.title": "Hoe werken campagnecodes?",
  "help.articles.howCampaignCodesWork.description": "Promocodes kunnen credits of korting geven bij checkout.",
  "help.articles.howCampaignCodesWork.body1": "Voer een geldige campagnecode in op de billing- of creditspagina. Elke actie heeft eigen limieten en vervaldatum.",
  "help.articles.creditsVsSubscriptions.title": "Credits vs abonnementen",
  "help.articles.creditsVsSubscriptions.description": "Wanneer credits kopen en wanneer een plan upgraden.",
  "help.articles.creditsVsSubscriptions.body1": "Koop credits als je prepaid saldo nodig hebt voor renders en generatie. Upgrade een plan als je regelmatig credits gebruikt en permanente korting wilt.",
  "help.articles.creditsVsSubscriptions.body2": "De meeste teams combineren beide: een plan voor korting plus top-up packs bij drukke weken.",
  "help.articles.monthlyVsYearly.title": "Wat is het verschil tussen maandelijks en jaarlijks?",
  "help.articles.monthlyVsYearly.description":
    "Beide opties geven dezelfde planvoordelen — jaarlijks is goedkoper per jaar.",
  "help.articles.monthlyVsYearly.body1":
    "Maandelijks betaal je elke maand (bijv. Creator €7,99/maand). Je kunt op elk moment opzeggen via Account → Billing.",
  "help.articles.monthlyVsYearly.body2":
    "Jaarlijks betaal je één keer per jaar (bijv. Creator €79,90/jaar). Dat is ongeveer 17% goedkoper dan 12 maandelijkse betalingen — vergelijkbaar met 2 maanden gratis.",
  "help.articles.gettingStarted.title": "Aan de slag met Studio",
  "help.articles.gettingStarted.description": "Van account naar eerste render in minder dan drie minuten.",
  "help.articles.gettingStarted.body1": "Maak een storyboard of personage, open Motion, upload frames en genereer je eerste clip.",
  "help.articles.gettingStarted.body2": "Volg de onboarding-checklist op je Studio-dashboard voor stap-voor-stap voortgang.",

