  "pricing.carryTitle": "Credits blijven van jou",
  "pricing.carryBody":
    "Gekochte credits blijven van jou. Zolang je abonnement actief is, schuiven credits onbeperkt door. Bij opzegging blijven resterende credits beschikbaar als prepaid tegoed.",
  "pricing.faq.title": "Veelgestelde vragen over prijzen",
  "pricing.faq.q1": "Verlopen credits?",
  "pricing.faq.a1":
    "Gekochte credits verlopen standaard niet. Bonus credits uit campagnes kunnen eigen regels hebben — die zie je bij het toepassen van een code.",
  "pricing.faq.q2": "Wat zit er in een abonnement?",
  "pricing.faq.a2":
    "Abonnementen geven goedkopere credit packs, meer opslag en premium functies. Er komen geen gratis maandelijkse credits bij.",
  "pricing.faq.q3": "Wat gebeurt er als ik mijn abonnement opzeg?",
  "pricing.faq.a3":
    "Je houdt elk credit dat al op je account staat. Planvoordelen stoppen, maar je saldo blijft beschikbaar als prepaid tegoed.",
  "pricing.faq.q4": "Kan ik credits kopen zonder abonnement?",
  "pricing.faq.a4": "Ja. Credit packs werken op elk plan, ook gratis. Abonnees betalen minder per pack.",
  "pricing.faq.q5": "Waar zie ik mijn saldo en bonnen?",
  "pricing.faq.a5": "Log in en open Facturatie & credits in je account voor saldo, transactiegeschiedenis en abonnementsbeheer.",
  "pricing.faq.q6": "Wat is het verschil tussen maandelijks en jaarlijks?",
  "pricing.faq.a6":
    "Maandelijks betaal je per maand en kun je elk moment opzeggen. Jaarlijks betaal je één keer per jaar tegen een lagere prijs — ongeveer 17% goedkoper dan 12 maandelijkse betalingen (2 maanden gratis). Dezelfde planvoordelen gelden in beide gevallen.",
  "pricing.usageLink": "Bekijk mijn verbruik",
  "pricing.billingLink": "Facturatie & credits",
  "pricing.createLink": "Start een project",

  "about.label": "Over",
  "about.title": "Het HomeCheff-ecosysteem",
  "about.subtitle":
    "HomeCheff is een professionele AI-motionstudio en creatorplatform — niet alleen één animatietool.",
  "about.vision.title": "Onze visie",
  "about.vision.body":
    "We verbinden planning, rendering en publicatie zodat creators consistente AI-films op studiokwaliteit kunnen produceren — van eerste videoverhaal tot final cut.",
  "about.products.homecheff.name": "HomeCheff",
  "about.products.homecheff.body": "Het paraplu-creatorplatform dat Motion, Studio en toekomstige lifestyleproducten verbindt.",
  "about.products.homegarden.name": "HomeGarden",
  "about.products.homegarden.body": "Buitenleven-inspiratie — gepland als complementair merk in het ecosysteem.",
  "about.products.homedesigner.name": "HomeDesigner",
  "about.products.homedesigner.body": "Interieurdesigntooling — gepland om assets en stijl te delen met Studio-producties.",
  "about.products.motion.name": "HomeCheff Motion",
  "about.products.motion.body": "AI-motionwizard, renderpipelines, voortgangsherstel en videoversionering.",
  "about.products.studio.name": "HomeCheff Studio",
  "about.products.studio.body": "Videoverhalen, personages, directors en scènebeelden voor herhaalbare productiekwaliteit.",
  "about.products.explore": "Verkennen",
  "about.cta": "Begin met maken",

